    ["Reroll"] = "Переролл",
    ["If the next stop <LightHighlight> is the [Winery] </>, obtain <LightHighlight> 60 </> units of <HyperLink stylename=\"Underline\" u=\"trainTradeItem=30307\"> [Gold-Medal Royal Ham] </>."] = "Если следующей остановкой <LightHighlight> является [Винодельня] </>, получите <LightHighlight> 60 единиц </> <HyperLink stylename=\"Underline\" u=\"trainTradeItem=30307\"> [Золотая медаль Королевской ветчины] </>.",
